require __DIR__.'/../includes/config.php';require __DIR__.'/../includes/functions.php';$u=require_role(['operator']);verify_csrf();$id=(int)($_GET['id']??$_POST['request_id']??0);$r=request_by_id($pdo,$id);if(!$r){http_response_code(404);exit('Request not found.');}$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';try{
 if($action==='assign'){$providerId=(int)($_POST['provider_id']??0);$st=$pdo->prepare('SELECT sp.*,u.full_name FROM service_providers sp JOIN users u ON u.id=sp.user_id WHERE sp.id=? AND sp.is_active=1');$st->execute([$providerId]);$provider=$st->fetch();if(!$provider)throw new RuntimeException('Choose an active provider.');$pdo->beginTransaction();$pdo->prepare('UPDATE requests SET provider_id=? WHERE id=?')->execute([$providerId,$id]);if((int)$r['status']<1){log_status($pdo,$id,1,$u['id'],'Assigned to '.$provider['full_name'].'.');}add_notification($pdo,(int)$r['owner_id'],$id,'Responder assigned','Your request '.$r['request_no'].' has been assigned to '.$provider['full_name'].'.');add_notification($pdo,(int)$provider['user_id'],$id,'New job assigned','You have been assigned request '.$r['request_no'].'.');$pdo->commit();$success='Provider assigned and status history updated.';}
 elseif($action==='status'){$new=(int)($_POST['status']??-1);if($new<0||$new>4)throw new RuntimeException('Invalid status.');if($new<(int)$r['status'])throw new RuntimeException('Status cannot move backwards.');if($new>(int)$r['status']+1)throw new RuntimeException('Move one status step at a time.');if($new>=2&&empty($r['provider_id']))throw new RuntimeException('Assign a service provider before moving the request beyond Assigned to Responder.');$pdo->beginTransaction();$lock=$pdo->prepare('SELECT status,provider_id FROM requests WHERE id=? FOR UPDATE');$lock->execute([$id]);$current=$lock->fetch();if(!$current)throw new RuntimeException('Request no longer exists.');$currentStatus=(int)$current['status'];if($new<$currentStatus||$new>$currentStatus+1)throw new RuntimeException('This request has changed. Refresh the page and choose the next valid status.');if($new>=2&&empty($current['provider_id']))throw new RuntimeException('Assign a service provider before moving the request beyond Assigned to Responder.');if($new!==(int)$currentStatus){log_status($pdo,$id,$new,$u['id'],trim($_POST['note']??'')?:'Updated by emergency centre operator.');add_notification($pdo,(int)$r['owner_id'],$id,'Request status updated',status_names()[$new].' for '.$r['request_no'].'.');if($r['provider_user_id'])add_notification($pdo,(int)$r['provider_user_id'],$id,'Job status updated',status_names()[$new].' for '.$r['request_no'].'.');}$pdo->commit();$success=$new===$currentStatus?'No change made; the status is already current.':'Status updated and history recorded.';}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not update this request.';}
 $r=request_by_id($pdo,$id);
}
$st=$pdo->query("SELECT sp.id,sp.service_type,u.full_name FROM service_providers sp JOIN users u ON u.id=sp.user_id WHERE sp.is_active=1 ORDER BY u.full_name");$providers=$st->fetchAll();$hist=status_history($pdo,$id);$att=$pdo->prepare('SELECT * FROM attachments WHERE request_id=? ORDER BY id DESC LIMIT 1');$att->execute([$id]);$photo=$att->fetch();$pageTitle='Manage Request';require __DIR__.'/../includes/header.php';?>
<div class="eyebrow">REQUEST DETAIL · <?=e($r['request_no'])?></div><h2><?=e($r['title'])?></h2><p class="subtext"><?=e($r['category_name'])?> · <?=e($r['township'])?></p><?php if($success):?><div class="flash"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?>
<div class="grid grid-2"><div class="card"><div style="display:flex;justify-content:space-between;gap:8px"><h3>Owner report</h3><span class="badge <?=status_class((int)$r['status'])?>"><?=e(status_names()[$r['status']])?></span></div><p><small class="muted">Owner</small><br><strong><?=e($r['owner_name'])?></strong> · <?=e($r['owner_phone'])?><br><small><?=e($r['owner_email'])?></small></p><p><small class="muted">Location</small><br><?=e($r['location'])?></p><p><small class="muted">Description</small><br><?=nl2br(e($r['description']))?></p><p><small class="muted">Priority</small><br><?=e(ucfirst($r['priority']))?></p><?php if($photo):?><img class="photo-preview" src="<?=BASE_URL?>/uploads/<?=e($photo['stored_name'])?>" alt="Uploaded issue photo"><?php endif;?></div>
<div class="grid"><div class="card"><h3>Assign service provider</h3><form method="post"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=$id?>"><input type="hidden" name="action" value="assign"><div class="field"><label>Authorised provider</label><select name="provider_id" required><option value="">Select provider</option><?php foreach($providers as $p):?><option value="<?=$p['id']?>" <?=((int)$r['provider_id']===(int)$p['id'])?'selected':''?>><?=e($p['full_name'])?> — <?=e($p['service_type'])?></option><?php endforeach;?></select></div><button class="btn btn-primary btn-block">Assign responder</button></form><p class="muted" style="font-size:11px">Assignment automatically records “Assigned to Responder” if the request was newly received.</p></div>
<div class="card"><h3>Update status</h3><form method="post"><?=csrf_field()?><input type="hidden" name="request_id" value="<?=$id?>"><input type="hidden" name="action" value="status"><div class="field"><label>Next status</label><select name="status" required><?php foreach(status_names() as $i=>$s):if($i<(int)$r['status']||$i>(int)$r['status']+1)continue;?><option value="<?=$i?>" <?=$i===(int)$r['status']?'selected':''?>><?=$i=== (int)$r['status']?'Current: ':''?><?=e($s)?></option><?php endforeach;?></select></div><div class="field"><label>Update note (optional)</label><input name="note" placeholder="e.g. Technician contacted owner"></div><button class="btn btn-dark btn-block">Save status update</button></form></div></div></div>
<div class="card" style="margin-top:16px"><h3>Recorded status history</h3><div class="timeline"><?php foreach($hist as $h):?><div class="timeline-item"><div class="timeline-marker"><?=((int)$h['status']===4)?'✓':((int)$h['status']+1)?></div><div class="timeline-copy"><strong><?=e(status_names()[$h['status']])?></strong><small><?=e(status_timestamp($h['created_at']))?> · <?=e($h['changed_by_name']??'System')?><?= $h['note']?' · '.e($h['note']):''?></small></div></div><?php endforeach;?></div><a class="btn btn-secondary" href="<?=BASE_URL?>/operator/requests.php">← Back to requests</a></div><?php require __DIR__.'/../includes/footer.php';?>
